'use strict';
const cases = {
  1: {title:'Где включить двухфакторный вход?',ticket:'Подскажите, где включить двухфакторный вход для моего аккаунта?',history:'Клиент подтвердил: интерфейс учебного Demo SaaS v2, роль — администратор.',facts:['Версия интерфейса: v2 (из истории).','Клиент — администратор аккаунта (из истории).'],missing:[],category:'Доступ',urgency:'Низкая',urgencyReason:'Вопрос о настройке; признаков недоступности сервиса нет.',mode:'answer',summary:'Клиент ищет настройку 2FA для своего аккаунта.',next:'Проверить версию источника и подтвердить текст ответа.',reply:'В учебном Demo SaaS v2 откройте «Профиль → Безопасность → Двухфакторный вход». Следуйте инструкции KB-DEMO-01 v2.',source:{id:'KB-DEMO-01',version:'v2',title:'Настройка 2FA в Demo SaaS',text:'Статус: утверждён для учебного сценария.\nДля администратора Demo SaaS v2: Профиль → Безопасность → Двухфакторный вход. Это вымышленная инструкция, не рекомендация для настоящего сервиса.'}},
  2: {title:'Интеграция перестала работать',ticket:'Со вчерашнего дня интеграция не работает. Помогите разобраться.',history:'Клиент сообщил время сбоя. Название интеграции и ошибка ещё не указаны.',facts:['Сбой замечен вчера (из обращения).'],missing:['Название интеграции и точный текст ошибки.'],category:'Интеграции',urgency:'Не оценена',urgencyReason:'Влияние и число затронутых пользователей неизвестны.',mode:'clarify',summary:'Для поиска причины не хватает описания интеграции и ошибки.',next:'Сверить историю и запросить недостающие технические сведения.',reply:'Уточните, пожалуйста, название интеграции и точный текст ошибки. Не присылайте пароли, токены или другие секреты.',source:null},
  3: {title:'Повторное списание по счёту',ticket:'По счёту DEMO-701 деньги списались дважды. Нужен возврат.',history:'Первый платёж подтверждён в синтетической истории. Повторный пока не проверен.',facts:['Номер учебного счёта: DEMO-701.','Повторное списание — сообщение клиента, не подтверждённый факт.'],missing:['Проверка платёжного журнала специалистом.'],category:'Платежи',urgency:'Средняя',urgencyReason:'Финансовый вопрос требует проверки; число затронутых клиентов неизвестно.',mode:'escalate',summary:'Клиент сообщает о двух списаниях и просит возврат.',next:'Выбрать платёжного специалиста и передать проверенный контекст.',reply:'Клиент сообщает о повторном списании по DEMO-701. Первое списание подтверждено; повторное требует проверки платёжного журнала. Возврат не обещан.',source:null},
  4: {title:'Проверка спорного предложения',ticket:'Мне нужно настроить двухфакторный вход в новой версии интерфейса.',history:'Текущая версия — v2. Предложение ссылается на неподтверждённую инструкцию v1.',facts:['Клиент использует интерфейс v2 (из истории).'],missing:['Утверждённый источник для текущей версии.'],category:'Доступ',urgency:'Низкая',urgencyReason:'Запрос на настройку; ущерб не сообщён.',mode:'answer',summary:'В предложении обнаружено несоответствие версии источника.',next:'Отклонить ошибочное предложение с причиной и продолжить вручную.',reply:'Перейдите в старое меню «Профиль → SMS».',source:{id:'KB-DEMO-OLD',version:'v1',title:'Устаревшая инструкция — не утверждена',text:'Учебный пример ошибочного основания. Статус: черновик; версия v1 не соответствует истории v2. Использовать для ответа нельзя.'},blocked:true}
};
const labels={answer:'Обоснованный ответ',clarify:'Уточнить данные',escalate:'Передать специалисту'};
const actions={answer:'Подтвердить учебную отправку ответа',clarify:'Подтвердить учебную отправку вопроса',escalate:'Подтвердить учебную передачу'};
const $=id=>document.getElementById(id);
let current=1, edited=false, finished=false, pending=null;
function setText(id,value){$(id).textContent=value;}
function list(id,values){$(id).replaceChildren();for(const value of values.length?values:['Нет.']){const item=document.createElement('li');item.textContent=value;$(id).append(item);}}
function audit(title,detail){const li=document.createElement('li'),bold=document.createElement('strong');bold.textContent=title+' · ';li.append(bold,document.createTextNode(detail));$('audit').append(li);}
function loadCase(number){
 current=number;edited=false;finished=false;pending=null;const item=cases[number];
 for(const button of document.querySelectorAll('[data-case]'))button.setAttribute('aria-current',String(Number(button.dataset.case)===number));
 setText('ticket-id','DEMO-01'+number+' / UC-0'+number);
 for(const [id,key] of [['title','title'],['ticket-text','ticket'],['history','history'],['category','category'],['urgency','urgency'],['urgency-reason','urgencyReason'],['summary','summary'],['next-step','next']])setText(id,item[key]);
 list('facts',item.facts);list('missing',item.missing);setText('mode',labels[item.mode]);setText('reply-label',item.mode==='escalate'?'Контекст для специалиста':'Черновик для проверки');
 $('reply').value=item.reply;$('reply').readOnly=true;$('reason').value='';$('queue').value='';$('queue-field').hidden=item.mode!=='escalate';$('sources').replaceChildren();
 if(item.source){const button=document.createElement('button');button.className='source';const title=document.createElement('strong'),meta=document.createElement('span');title.textContent=item.source.title;meta.textContent=item.source.id+' · '+item.source.version+' · открыть источник';button.append(title,meta);button.addEventListener('click',()=>{setText('source-title',item.source.title);setText('source-meta',item.source.id+' · '+item.source.version);setText('source-text',item.source.text);$('source-dialog').showModal();});$('sources').append(button);}else{setText('sources','Утверждённый источник ответа отсутствует.');}
 setText('review-status','Ожидает проверки');$('prepare').disabled=Boolean(item.blocked);$('edit').disabled=false;$('reject').disabled=false;$('warning').hidden=!item.blocked;setText('warning',item.blocked?'Отправка недоступна: источник не утверждён и не соответствует истории.':'');setText('feedback','');$('audit').replaceChildren();audit('Исходное предложение',labels[item.mode]+'. '+item.reply);
}
for(const button of document.querySelectorAll('[data-case]'))button.addEventListener('click',()=>loadCase(Number(button.dataset.case)));
$('reset').addEventListener('click',()=>loadCase(current));
$('edit').addEventListener('click',()=>{if(finished)return;$('reply').readOnly=false;$('reply').focus();setText('feedback','Исправьте текст и укажите причину. Затем подтвердите его отдельно.');});
$('reply').addEventListener('input',()=>{edited=true;pending=null;if($('confirm-dialog').open)$('confirm-dialog').close();setText('review-status','Текст изменён — нужна проверка');});
$('prepare').addEventListener('click',()=>{
 const item=cases[current];if(finished||item.blocked)return;const text=$('reply').value.trim(),reason=$('reason').value.trim(),queue=$('queue').value;
 if(!text){setText('feedback','Текст не должен быть пустым.');return;}if(edited&&!reason){setText('feedback','Укажите причину правки.');return;}if(item.mode==='escalate'&&!queue){setText('feedback','Выберите очередь специалиста.');return;}
 pending={text,reason,queue,edited};setText('confirm-title',actions[item.mode]);setText('confirm-detail',item.mode==='escalate'?'Адресат: '+$('queue').selectedOptions[0].textContent:'Проверьте финальный текст и показанные основания.');setText('confirm-text',text);$('confirm-dialog').showModal();
});
$('confirm').addEventListener('click',()=>{
 if(!pending||finished)return;const item=cases[current];
 if(pending.text!==$('reply').value.trim()||pending.queue!==$('queue').value||pending.reason!==$('reason').value.trim()){$('confirm-dialog').close();pending=null;setText('feedback','Данные изменились. Проверьте их заново.');return;}
 audit('Решение оператора',actions[item.mode]+(pending.edited?' · текст исправлен':'')+(pending.reason?' · причина: '+pending.reason:''));audit('Финальный текст',pending.text);finish(item.mode==='escalate'?'Передача смоделирована':'Отправка смоделирована');$('confirm-dialog').close();setText('feedback','Действие подтверждено в учебной симуляции.');pending=null;
});
$('reject').addEventListener('click',()=>{if(finished)return;const reason=$('reason').value.trim();if(!reason){setText('feedback','Укажите причину отклонения.');$('reason').focus();return;}audit('Решение оператора','Предложение отклонено. Причина: '+reason);finish('Отклонено');setText('feedback','Продолжайте разбор вручную. Отправка и передача не моделировались.');});
function finish(status){finished=true;setText('review-status',status);for(const id of ['prepare','edit','reject'])$(id).disabled=true;$('reply').readOnly=true;}
loadCase(1);
